:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --accent-pressed: #4a43b0;
  --swatch-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c8;
  margin-bottom: 24px;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 28px;
}

.swatch {
  flex: 1 1 100px;
  min-width: 80px;
  border-radius: var(--swatch-radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
}

.color-block {
  height: 100px;
  width: 100%;
  transition: background 0.2s ease;
}

.hex-label {
  background: #1e1e2f;
  color: #f0f0f5;
  font-size: 1rem;
  font-weight: 600;
  padding: 8px 4px;
  text-align: center;
  letter-spacing: 0.5px;
  font-variant-numeric: tabular-nums;
}

.lock-btn {
  background: #1e1e2f;
  color: #b0b0c8;
  border: none;
  border-top: 1px solid #3a3a55;
  padding: 8px 4px;
  font-size: 0.9rem;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
}

.lock-btn:hover {
  background: #2a2a40;
  color: #f0f0f5;
}

.lock-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: 0 0 var(--swatch-radius) var(--swatch-radius);
}

.lock-btn:active {
  background: #3a3a55;
}

.lock-btn[aria-pressed="true"] {
  color: #ffd166;
  background: #2a2a40;
}

.lock-icon {
  font-size: 1rem;
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 14px 48px;
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  width: 100%;
  max-width: 280px;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
    border-radius: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .swatches {
    gap: 8px;
  }
  .swatch {
    flex: 1 1 80px;
    min-width: 60px;
  }
  .color-block {
    height: 80px;
  }
  .hex-label {
    font-size: 0.85rem;
    padding: 6px 2px;
  }
  .lock-btn {
    font-size: 0.8rem;
    padding: 6px 2px;
  }
  .generate-btn {
    padding: 12px 32px;
    font-size: 1rem;
  }
}

@media (max-width: 360px) {
  .swatch {
    flex: 1 1 100%;
  }
  .color-block {
    height: 60px;
  }
}

(function () {
  'use strict';

  const SWATCH_COUNT = 5;
  const swatchesContainer = document.getElementById('swatches');
  const generateBtn = document.getElementById('generate');

  const palettes = [];
  const locks = new Array(SWATCH_COUNT).fill(false);

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return ('#' + f(0) + f(8) + f(4)).toUpperCase();
  }

  function createSwatch(index) {
    const swatch = document.createElement('div');
    swatch.className = 'swatch';

    const colorBlock = document.createElement('div');
    colorBlock.className = 'color-block';
    colorBlock.id = 'color-' + index;

    const hexLabel = document.createElement('div');
    hexLabel.className = 'hex-label';
    hexLabel.id = 'hex-' + index;
    hexLabel.textContent = '#000000';

    const lockBtn = document.createElement('button');
    lockBtn.className = 'lock-btn';
    lockBtn.type = 'button';
    lockBtn.setAttribute('aria-pressed', 'false');
    lockBtn.setAttribute('aria-label', 'Lock color ' + (index + 1));
    lockBtn.innerHTML = '<span class="lock-icon" aria-hidden="true">🔓</span> Lock';
    lockBtn.addEventListener('click', () => toggleLock(index, lockBtn));

    swatch.appendChild(colorBlock);
    swatch.appendChild(hexLabel);
    swatch.appendChild(lockBtn);
    return swatch;
  }

  function toggleLock(index, btn) {
    locks[index] = !locks[index];
    btn.setAttribute('aria-pressed', locks[index].toString());
    btn.innerHTML = locks[index]
      ? '<span class="lock-icon" aria-hidden="true">🔒</span> Locked'
      : '<span class="lock-icon" aria-hidden="true">🔓</span> Lock';
    btn.setAttribute('aria-label', (locks[index] ? 'Unlock color ' : 'Lock color ') + (index + 1));
  }

  function generatePalette() {
    const baseHue = Math.random() * 360;
    const newColors = [];

    for (let i = 0; i < SWATCH_COUNT; i++) {
      if (locks[i]) {
        newColors.push(palettes[i]);
      } else {
        const hueOffset = (i * 72) % 360;
        const hue = (baseHue + hueOffset) % 360;
        const sat = 60 + Math.random() * 20;
        const light = 45 + Math.random() * 20;
        newColors.push(hslToHex(hue, sat, light));
      }
    }

    for (let i = 0; i < SWATCH_COUNT; i++) {
      palettes[i] = newColors[i];
    }

    render();
  }

  function render() {
    for (let i = 0; i < SWATCH_COUNT; i++) {
      const color = palettes[i];
      const colorBlock = document.getElementById('color-' + i);
      const hexLabel = document.getElementById('hex-' + i);
      if (colorBlock) colorBlock.style.backgroundColor = color;
      if (hexLabel) hexLabel.textContent = color;
    }
  }

  function init() {
    for (let i = 0; i < SWATCH_COUNT; i++) {
      swatchesContainer.appendChild(createSwatch(i));
    }
    generatePalette();
    generateBtn.addEventListener('click', generatePalette);
  }

  init();
})();
